     1→/**
     2→ * Image Generation API Route
     3→ * POST /api/generate-image
     4→ *
     5→ * Handles outfit image generation requests using OpenRouter's Gemini 2.5 Flash Preview model
     6→ *
     7→ * Features:
     8→ * - Server-side rate limiting (10 requests per minute per IP)
     9→ * - Request validation
    10→ * - Error handling with appropriate HTTP status codes
    11→ * - Logging for debugging
    12→ */
    13→
    14→import { NextRequest, NextResponse } from 'next/server';
    15→import { OpenRouterImageClient } from '@/lib/services/image-generation-service';
    16→import type { ImageGenerationRequest, FlatLayItem } from '@/lib/types/image-types';
    17→import fs from 'fs';
    18→import path from 'path';
    19→import { spawn } from 'child_process';
    20→
    21→/**
    22→ * Rate limiting configuration
    23→ * Tracks request counts per IP address
    24→ */
    25→const rateLimitMap = new Map<string, { count: number; resetTime: number }>();
    26→const RATE_LIMIT_WINDOW = 60000; // 1 minute in milliseconds
    27→const RATE_LIMIT_MAX_REQUESTS = 10;
    28→
    29→/**
    30→ * Checks if request is rate limited
    31→ *
    32→ * @param ip - Client IP address
    33→ * @returns true if rate limited, false if allowed
    34→ */
    35→function isRateLimited(ip: string): boolean {
    36→  const now = Date.now();
    37→  const record = rateLimitMap.get(ip);
    38→
    39→  // No record or window expired - create new record
    40→  if (!record || now > record.resetTime) {
    41→    rateLimitMap.set(ip, {
    42→      count: 1,
    43→      resetTime: now + RATE_LIMIT_WINDOW,
    44→    });
    45→    return false;
    46→  }
    47→
    48→  // Increment count
    49→  record.count++;
    50→
    51→  // Check if over limit
    52→  if (record.count > RATE_LIMIT_MAX_REQUESTS) {
    53→    return true;
    54→  }
    55→
    56→  return false;
    57→}
    58→
    59→/**
    60→ * Gets client IP address from request
    61→ *
    62→ * @param request - Next.js request object
    63→ * @returns IP address string
    64→ */
    65→function getClientIP(request: NextRequest): string {
    66→  // Try various headers that might contain the real IP
    67→  const forwarded = request.headers.get('x-forwarded-for');
    68→  if (forwarded) {
    69→    return forwarded.split(',')[0].trim();
    70→  }
    71→
    72→  const realIP = request.headers.get('x-real-ip');
    73→  if (realIP) {
    74→    return realIP;
    75→  }
    76→
    77→  // Fallback to a default value
    78→  return 'unknown';
    79→}
    80→
    81→/**
    82→ * Ensures a directory exists, creating it if necessary
    83→ *
    84→ * @param dirPath - Absolute path to the directory
    85→ */
    86→function ensureDirectoryExists(dirPath: string): void {
    87→  if (!fs.existsSync(dirPath)) {
    88→    fs.mkdirSync(dirPath, { recursive: true });
    89→    console.log('[API] Created directory:', dirPath);
    90→  }
    91→}
    92→
    93→/**
    94→ * Generates a unique filename for an outfit image
    95→ *
    96→ * @returns Filename in format: outfit-{timestamp}.png
    97→ */
    98→function generateImageFilename(): string {
    99→  const timestamp = Date.now();
   100→  return `outfit-${timestamp}.png`;
   101→}
   102→
   103→/**
   104→ * Removes background from an image file using rembg Python script
   105→ *
   106→ * @param inputPath - Absolute path to the input image
   107→ * @param outputPath - Absolute path to save the output image
   108→ * @returns Promise that resolves to true on success, false on failure
   109→ */
   110→async function removeBackgroundFromFile(inputPath: string, outputPath: string): Promise<boolean> {
   111→  return new Promise((resolve) => {
   112→    const scriptPath = path.join(process.cwd(), '..', '..', 'scripts', 'image_processing', 'remove_bg_rembg.py');
   113→
   114→    console.log('[API] Running background removal:', { inputPath, outputPath, scriptPath });
   115→
   116→    const python = spawn('python3', [scriptPath, inputPath, outputPath]);
   117→
   118→    let stderr = '';
   119→
   120→    python.stderr.on('data', (data) => {
   121→      stderr += data.toString();
   122→      console.log('[API] Background removal:', data.toString().trim());
   123→    });
   124→
   125→    python.on('close', (code) => {
   126→      if (code === 0) {
   127→        console.log('[API] Background removal completed successfully');
   128→        resolve(true);
   129→      } else {
   130→        console.error('[API] Background removal failed with code:', code);
   131→        console.error('[API] stderr:', stderr);
   132→        resolve(false);
   133→      }
   134→    });
   135→
   136→    python.on('error', (err) => {
   137→      console.error('[API] Failed to spawn background removal process:', err);
   138→      resolve(false);
   139→    });
   140→  });
   141→}
   142→
   143→/**
   144→ * Auto-crops image to the bounding box of non-transparent pixels with padding
   145→ *
   146→ * @param inputPath - Absolute path to the input image
   147→ * @param outputPath - Absolute path to save the output image
   148→ * @returns Promise that resolves to true on success, false on failure
   149→ */
   150→async function autoCropSubject(inputPath: string, outputPath: string): Promise<boolean> {
   151→  return new Promise((resolve) => {
   152→    const scriptPath = path.join(process.cwd(), '..', '..', 'scripts', 'image_processing', 'auto_crop_subject.py');
   153→
   154→    console.log('[API] Running auto-crop:', { inputPath, outputPath, scriptPath });
   155→
   156→    const python = spawn('python3', [scriptPath, inputPath, outputPath]);
   157→
   158→    let stderr = '';
   159→
   160→    python.stderr.on('data', (data) => {
   161→      stderr += data.toString();
   162→      console.log('[API] Auto-crop:', data.toString().trim());
   163→    });
   164→
   165→    python.on('close', (code) => {
   166→      if (code === 0) {
   167→        console.log('[API] Auto-crop completed successfully');
   168→        resolve(true);
   169→      } else {
   170→        console.error('[API] Auto-crop failed with code:', code);
   171→        console.error('[API] stderr:', stderr);
   172→        resolve(false);
   173→      }
   174→    });
   175→
   176→    python.on('error', (err) => {
   177→      console.error('[API] Failed to spawn auto-crop process:', err);
   178→      resolve(false);
   179→    });
   180→  });
   181→}
   182→
   183→/**
   184→ * Saves a base64-encoded image to disk as a PNG file
   185→ *
   186→ * @param base64Data - Base64 image data (with or without data URL prefix)
   187→ * @param filename - Name of the file to save
   188→ * @returns Relative public URL path to the saved image
   189→ * @throws Error if file save fails
   190→ */
   191→function saveBase64Image(base64Data: string, filename: string): string {
   192→  // Strip data URL prefix if present (e.g., "data:image/png;base64,")
   193→  const base64Content = base64Data.includes(',')
   194→    ? base64Data.split(',')[1]
   195→    : base64Data;
   196→
   197→  // Construct absolute path to the public/generated-images directory
   198→  const publicDir = path.join(process.cwd(), 'public', 'generated-images');
   199→  ensureDirectoryExists(publicDir);
   200→
   201→  const filePath = path.join(publicDir, filename);
   202→
   203→  // Convert base64 to buffer and write to file
   204→  const imageBuffer = Buffer.from(base64Content, 'base64');
   205→  fs.writeFileSync(filePath, imageBuffer);
   206→
   207→  console.log('[API] Saved image to:', filePath);
   208→
   209→  // Return public URL path (relative)
   210→  return `/generated-images/${filename}`;
   211→}
   212→
   213→/**
   214→ * POST handler for image generation
   215→ *
   216→ * Request body:
   217→ * {
   218→ *   description: string,
   219→ *   style?: {
   220→ *     photographyStyle?: string,
   221→ *     composition?: string,
   222→ *     lighting?: string,
   223→ *     aestheticContext?: string
   224→ *   }
   225→ * }
   226→ *
   227→ * Response on success:
   228→ * {
   229→ *   success: true,
   230→ *   imageUrl: string,        // Public URL path (e.g., /generated-images/outfit-1732800000000.png)
   231→ *   imageBase64: string,      // Base64-encoded image data
   232→ *   error?: undefined,
   233→ *   message?: undefined
   234→ * }
   235→ *
   236→ * Response on failure:
   237→ * {
   238→ *   success: false,
   239→ *   imageUrl?: undefined,
   240→ *   imageBase64?: undefined,
   241→ *   error: string,
   242→ *   message: string
   243→ * }
   244→ */
   245→export async function POST(request: NextRequest) {
   246→  const startTime = Date.now();
   247→
   248→  try {
   249→    // Get client IP for rate limiting
   250→    const clientIP = getClientIP(request);
   251→
   252→    console.log('[API] Image generation request received from IP:', clientIP);
   253→
   254→    // Check rate limiting
   255→    if (isRateLimited(clientIP)) {
   256→      console.warn('[API] Rate limit exceeded for IP:', clientIP);
   257→      return NextResponse.json(
   258→        {
   259→          success: false,
   260→          error: 'RATE_LIMITED',
   261→          message: 'Too many requests. Please wait a minute before trying again.',
   262→        },
   263→        {
   264→          status: 429,
   265→          headers: {
   266→            'Retry-After': '60',
   267→          },
   268→        }
   269→      );
   270→    }
   271→
   272→    // Check if OPENROUTER_API_KEY is configured
   273→    const apiKey = process.env.OPENROUTER_API_KEY;
   274→    if (!apiKey) {
   275→      console.error('[API] OPENROUTER_API_KEY not configured');
   276→      return NextResponse.json(
   277→        {
   278→          success: false,
   279→          error: 'SERVICE_UNAVAILABLE',
   280→          message: 'Image generation service is not configured. Please contact support.',
   281→        },
   282→        { status: 503 }
   283→      );
   284→    }
   285→
   286→    // Parse request body
   287→    let body: ImageGenerationRequest;
   288→    try {
   289→      body = await request.json();
   290→    } catch (error) {
   291→      console.error('[API] Invalid JSON in request body:', error);
   292→      return NextResponse.json(
   293→        {
   294→          success: false,
   295→          error: 'INVALID_REQUEST',
   296→          message: 'Invalid request format',
   297→        },
   298→        { status: 400 }
   299→      );
   300→    }
   301→
   302→    // Validate request body
   303→    const { description, style, referenceImage, secondaryReferenceImage, generationType, flatLayItems, occasionContext } = body;
   304→
   305→    // Flat-lay generation requires items instead of description
   306→    if (generationType === 'flat-lay') {
   307→      if (!flatLayItems || !Array.isArray(flatLayItems) || flatLayItems.length === 0) {
   308→        console.error('[API] Missing or invalid items for flat-lay generation');
   309→        return NextResponse.json(
   310→          {
   311→            success: false,
   312→            error: 'INVALID_ITEMS',
   313→            message: 'At least one item is required for flat-lay generation',
   314→          },
   315→          { status: 400 }
   316→        );
   317→      }
   318→    } else if (!description || typeof description !== 'string' || description.trim() === '') {
   319→      console.error('[API] Missing or invalid description');
   320→      return NextResponse.json(
   321→        {
   322→          success: false,
   323→          error: 'INVALID_DESCRIPTION',
   324→          message: 'Outfit description is required',
   325→        },
   326→        { status: 400 }
   327→      );
   328→    }
   329→
   330→    // Validate description length (3000 chars for fitting-model, 1000 for outfit)
   331→    // Skip validation for flat-lay since it uses items instead of description
   332→    if (generationType !== 'flat-lay') {
   333→      const maxDescriptionLength = (generationType === 'fitting-model' || generationType === 'try-on' || generationType === 'try-on-dual') ? 3000 : 1000;
   334→      if (description && description.length > maxDescriptionLength) {
   335→        console.error('[API] Description too long:', description.length);
   336→        return NextResponse.json(
   337→          {
   338→            success: false,
   339→            error: 'DESCRIPTION_TOO_LONG',
   340→            message: `Description is too long. Please keep it under ${maxDescriptionLength} characters.`,
   341→          },
   342→          { status: 400 }
   343→        );
   344→      }
   345→    }
   346→
   347→    // Validate referenceImage format when provided with fitting-model, try-on, or try-on-dual generation
   348→    if ((generationType === 'fitting-model' || generationType === 'try-on' || generationType === 'try-on-dual') && referenceImage) {
   349→      if (typeof referenceImage !== 'string' || referenceImage.trim() === '') {
   350→        console.error('[API] Invalid reference image for', generationType, 'generation');
   351→        return NextResponse.json(
   352→          {
   353→            success: false,
   354→            error: 'INVALID_REFERENCE_IMAGE',
   355→            message: 'Reference image must be a valid string',
   356→          },
   357→          { status: 400 }
   358→        );
   359→      }
   360→
   361→      if (!referenceImage.startsWith('data:image/')) {
   362→        console.error('[API] Invalid reference image format');
   363→        return NextResponse.json(
   364→          {
   365→            success: false,
   366→            error: 'INVALID_REFERENCE_IMAGE_FORMAT',
   367→            message: 'Reference image must be a base64 data URL (e.g., data:image/jpeg;base64,...)',
   368→          },
   369→          { status: 400 }
   370→        );
   371→      }
   372→    }
   373→
   374→    // Validate that try-on and try-on-dual generation require a reference image
   375→    if ((generationType === 'try-on' || generationType === 'try-on-dual') && !referenceImage) {
   376→      console.error('[API] Missing reference image for', generationType, 'generation');
   377→      return NextResponse.json(
   378→        {
   379→          success: false,
   380→          error: 'MISSING_REFERENCE_IMAGE',
   381→          message: 'Reference image (fitting model) is required for try-on generation',
   382→        },
   383→        { status: 400 }
   384→      );
   385→    }
   386→
   387→    // Validate secondaryReferenceImage format when provided (required for try-on-dual)
   388→    if (generationType === 'try-on-dual') {
   389→      if (!secondaryReferenceImage) {
   390→        console.error('[API] Missing secondary reference image for try-on-dual generation');
